/** Explicit configuration: never provision a development identity service implicitly. */
export function accountAuthConfigured(env: NodeJS.ProcessEnv = process.env): boolean {
  return Boolean(env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY?.trim() && env.CLERK_SECRET_KEY?.trim());
}

/** A local demonstration can never spend AI credits or bypass deployed authentication. */
export function localAccountDemo(env: NodeJS.ProcessEnv = process.env): boolean {
  return env.NESALIO_LOCAL_DEMO === "1" && env.DISABLE_AI === "1" && !env.VERCEL && env.NODE_ENV !== "production";
}

export function accountOrigins(env: NodeJS.ProcessEnv = process.env): string[] {
  const candidates = [env.NEXT_PUBLIC_APP_URL];
  for (const host of [env.VERCEL_URL, env.VERCEL_PROJECT_PRODUCTION_URL]) {
    if (host) candidates.push(`https://${host}`);
  }
  if (!env.VERCEL && env.NODE_ENV !== "production") candidates.push("http://localhost:3000", "http://127.0.0.1:3000");
  const origins = new Set<string>();
  for (const value of candidates) {
    if (!value) continue;
    try {
      const url = new URL(value);
      if (url.hostname.includes("*") || url.username || url.password) continue;
      if (url.protocol === "https:" || (!env.VERCEL && env.NODE_ENV !== "production" && url.protocol === "http:")) origins.add(url.origin);
    } catch { /* Invalid configuration does not create an allowed origin. */ }
  }
  return [...origins];
}

import { auth } from "@clerk/nextjs/server";
import { encodeLine } from "@/domain/tutor/ndjson";
import { accountAuthConfigured, accountOrigins, localAccountDemo } from "./authConfig";

type Access = { ok: true; userId: string } | { ok: false; response: Response };

function denied(status: number, message: string, ndjson: boolean): Access {
  const headers = { "Cache-Control": "no-store", "Vary": "Cookie, Origin" };
  return {
    ok: false,
    response: ndjson
      ? new Response(encodeLine({ kind: "error", code: "upstream", message }), {
          status, headers: { ...headers, "Content-Type": "application/x-ndjson; charset=utf-8" },
        })
      : Response.json({ error: message }, { status, headers }),
  };
}

/** Authenticate at the operation itself, before reading bodies or calling paid services. */
export async function requireAccount(request: Request, ndjson = false): Promise<Access> {
  const origin = request.headers.get("origin");
  if (request.headers.get("sec-fetch-site") === "cross-site" || (origin !== null && !accountOrigins().includes(origin))) {
    return denied(403, "Cette requête ne vient pas de Nesalio.", ndjson);
  }
  if (localAccountDemo()) return { ok: true, userId: "local-demo" };
  if (!accountAuthConfigured()) return denied(503, "La connexion est temporairement indisponible. Réessaie plus tard.", ndjson);
  try {
    // Session cookies only: API keys and machine tokens do not identify a student.
    const session = await auth({ acceptsToken: "session_token" });
    if (!session.userId) return denied(401, "Connecte-toi pour continuer. Si ta session a expiré, recharge la page.", ndjson);
    return { ok: true, userId: session.userId };
  } catch {
    return denied(503, "La connexion est temporairement indisponible. Réessaie plus tard.", ndjson);
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const { session } = vi.hoisted(() => ({ session: vi.fn() }));
vi.mock("@clerk/nextjs/server", () => ({ auth: session }));

import { requireAccount } from "./account";
import { accountOrigins, localAccountDemo } from "./authConfig";
import { createSessionLimits } from "./rateLimit";

const request = (headers: Record<string, string> = {}) => new Request("https://app.nesalio.com/api/tutor", {
  method: "POST", headers: { origin: "https://app.nesalio.com", ...headers }, body: "{}",
});

beforeEach(() => {
  vi.stubEnv("NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY", "pk_test_placeholder");
  vi.stubEnv("CLERK_SECRET_KEY", "sk_test_placeholder");
  vi.stubEnv("NEXT_PUBLIC_APP_URL", "https://app.nesalio.com");
  vi.stubEnv("NESALIO_LOCAL_DEMO", "0");
  session.mockReset();
  session.mockResolvedValue({ userId: "user_alice" });
});
afterEach(() => vi.unstubAllEnvs());

describe("API account boundary", () => {
  it("refuses anonymous requests before consuming the body, including forged identity headers", async () => {
    session.mockResolvedValue({ userId: null });
    const input = request({ "x-nesalio-account": "user_alice", "x-nesalio-session": crypto.randomUUID() });
    const result = await requireAccount(input, true);
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("Anonymous access allowed");
    expect(result.response.status).toBe(401);
    expect(result.response.headers.get("content-type")).toContain("application/x-ndjson");
    expect(result.response.headers.get("cache-control")).toBe("no-store");
    expect(input.bodyUsed).toBe(false);
  });

  it("denies cross-origin and cross-site requests before consulting authentication", async () => {
    const cases: Record<string, string>[] = [{ origin: "https://untrusted.example" }, { origin: "null" }, { "sec-fetch-site": "cross-site" }];
    for (const headers of cases) {
      const result = await requireAccount(request(headers));
      expect(result.ok).toBe(false);
      if (!result.ok) expect(result.response.status).toBe(403);
    }
    expect(session).not.toHaveBeenCalled();
  });

  it("fails closed if keys are missing or authentication is unavailable", async () => {
    vi.stubEnv("CLERK_SECRET_KEY", "");
    const missing = await requireAccount(request());
    if (missing.ok) throw new Error("Unconfigured access allowed");
    expect(missing.response.status).toBe(503);
    expect(session).not.toHaveBeenCalled();
    vi.stubEnv("CLERK_SECRET_KEY", "sk_test_placeholder");
    session.mockRejectedValue(new Error("provider unavailable with sensitive details"));
    const failed = await requireAccount(request());
    if (failed.ok) throw new Error("Failed authentication allowed");
    expect(failed.response.status).toBe(503);
    expect(await failed.response.text()).not.toContain("sensitive details");
  });

  it("uses the verified session identity, accepting only session tokens", async () => {
    expect(await requireAccount(request())).toEqual({ ok: true, userId: "user_alice" });
    expect(session).toHaveBeenCalledWith({ acceptsToken: "session_token" });
  });

  it("does not reset an account quota when the client changes its navigation ID", () => {
    const limits = createSessionLimits({ limit: 1, windowMs: 60_000 });
    expect(limits.check(new Headers({ "x-nesalio-session": "session-one" }), 10, "user_alice").allowed).toBe(true);
    expect(limits.check(new Headers({ "x-nesalio-session": "session-two" }), 11, "user_alice").allowed).toBe(false);
    expect(limits.check(new Headers({ "x-nesalio-session": "session-two" }), 12, "user_bob").allowed).toBe(true);
  });

  it("cannot enable local bypass on Vercel, in production, or with live AI", () => {
    const demo = { NESALIO_LOCAL_DEMO: "1", DISABLE_AI: "1", NODE_ENV: "development" } as NodeJS.ProcessEnv;
    expect(localAccountDemo(demo)).toBe(true);
    expect(localAccountDemo({ ...demo, VERCEL: "1" })).toBe(false);
    expect(localAccountDemo({ ...demo, NODE_ENV: "production" })).toBe(false);
    expect(localAccountDemo({ ...demo, DISABLE_AI: "0" })).toBe(false);
  });

  it("does not trust wildcard or malformed origin settings", () => {
    expect(accountOrigins({ NODE_ENV: "production", NEXT_PUBLIC_APP_URL: "https://*.vercel.app", VERCEL_URL: "preview.vercel.app" } as NodeJS.ProcessEnv))
      .toEqual(["https://preview.vercel.app"]);
    expect(accountOrigins({ NODE_ENV: "production", NEXT_PUBLIC_APP_URL: "not a URL" } as NodeJS.ProcessEnv)).toEqual([]);
  });
});

