 * adresse IP (fenêtre glissante, en mémoire).
 *
 * Par session : plusieurs personnes derrière la même adresse (une classe sur
 * le Wi-Fi de l'école) ont chacune leur propre limite. Le plafond par adresse
 * empêche de contourner la limite en changeant de session à chaque requête.
 *
 * Suffisant pour un prototype : chaque instance serverless garde son propre
 * compteur, donc la limite réelle est approximative. Pour la production,
 * remplacer le magasin par un stockage partagé (Upstash Redis, Vercel KV…)
 * sans toucher aux appelants.
 */
export interface RateLimitResult {
  allowed: boolean;
  retryAfterSeconds: number;
}

export interface RateLimiter {
  check(key: string, now?: number): RateLimitResult;
}

export function createRateLimiter(options: { limit: number; windowMs: number; maxKeys?: number }): RateLimiter {
  const hits = new Map<string, number[]>();
  const maxKeys = options.maxKeys ?? 10_000;

  return {
    check(key, now = Date.now()) {
      const since = now - options.windowMs;
      const recent = (hits.get(key) ?? []).filter((t) => t > since);
      if (recent.length >= options.limit) {
        hits.set(key, recent);
        const retryAfterSeconds = Math.ceil((recent[0]! + options.windowMs - now) / 1000);
        return { allowed: false, retryAfterSeconds };
      }
      recent.push(now);
      hits.delete(key); // réinsertion : la Map garde les clés les plus récentes à la fin
      hits.set(key, recent);
      if (hits.size > maxKeys) hits.delete(hits.keys().next().value!);
      return { allowed: true, retryAfterSeconds: 0 };
    },
  };
}

/** Adresse du client derrière le proxy de Vercel. */
export function clientKey(headers: Headers): string {
  const forwarded = headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  return forwarded || headers.get("x-real-ip") || "anonyme";
}

/** Clés d'une requête : la session si le navigateur l'envoie (sinon l'adresse), et l'adresse. */
export function requestKeys(headers: Headers, accountId?: string): { user: string; ip: string; session: string | null } {
  const ip = clientKey(headers);
  const raw = headers.get(SESSION_HEADER);
  const session = isSessionId(raw) ? raw : null;
  return { user: accountId ? `u:${accountId}` : session ? `s:${session}` : `ip:${ip}`, ip, session };
}

/** Une limite par session et un plafond par adresse (par défaut 12 fois la limite d'une session). */
export function createSessionLimits(options: { limit: number; windowMs: number; ipFactor?: number }) {
  const perUser = createRateLimiter({ limit: options.limit, windowMs: options.windowMs });
  const perIp = createRateLimiter({ limit: options.limit * (options.ipFactor ?? 12), windowMs: options.windowMs });
  return {
    check(headers: Headers, now = Date.now(), accountId?: string): RateLimitResult & { session: string | null } {
      const keys = requestKeys(headers, accountId);
      const ip = perIp.check(keys.ip, now);
      if (!ip.allowed) return { ...ip, session: keys.session };
      return { ...perUser.check(keys.user, now), session: keys.session };
    },
  };
}
export type SessionLimits = ReturnType<typeof createSessionLimits>;

/** Petits utilitaires partagés par les routes de l'API. */
import type { SessionLimits } from "./rateLimit";

export function jsonError(status: number, message: string, extra: Record<string, string> = {}) {
  return Response.json({ error: message }, { status, headers: { "Cache-Control": "no-store", ...extra } });
}

/** Coupe la lecture à la limite réelle en octets, même sans Content-Length. */
export async function readBoundedText(request: Request, maxBytes: number): Promise<
  { ok: true; text: string } | { ok: false; status: 400 | 413 }
> {
  if (!request.body) return { ok: true, text: "" };
  const reader = request.body.getReader();
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let bytes = 0;
  let text = "";
  try {
    for (;;) {
      const chunk = await reader.read();
      if (chunk.done) break;
      bytes += chunk.value.byteLength;
      if (bytes > maxBytes) {
        await reader.cancel().catch(() => undefined);
        return { ok: false, status: 413 };
      }
      text += decoder.decode(chunk.value, { stream: true });
    }
    return { ok: true, text: text + decoder.decode() };
  } catch {
    await reader.cancel().catch(() => undefined);
    return { ok: false, status: 400 };
  } finally { reader.releaseLock(); }
}

/** Lit un corps JSON en refusant ce qui dépasse `maxBytes`. */
export async function readJson(request: Request, maxBytes: number): Promise<{ ok: true; body: unknown } | { ok: false; response: Response }> {
  const raw = await readBoundedText(request, maxBytes);
  if (!raw.ok) return { ok: false, response: jsonError(raw.status, raw.status === 413 ? "Requête trop volumineuse." : "Requête illisible.") };
  try {
    return { ok: true, body: JSON.parse(raw.text) };
  } catch {
    return { ok: false, response: jsonError(400, "Requête illisible.") };
  }
}

export function checkRate(limits: SessionLimits, request: Request, accountId?: string): Response | null {
  const limit = limits.check(request.headers, undefined, accountId);
  if (limit.allowed) return null;
  return jsonError(429, "Trop de demandes d'un coup. Réessaie dans quelques minutes.", {
    "Retry-After": String(limit.retryAfterSeconds),
  });
}

#!/usr/bin/env node
/**
 * Joue un scénario contre un déploiement (vrai modèle, élève simulé) et garde
 * tout : le rapport de /api/diagnostic et les événements bruts de chaque tour,
 * au format de rejeu (tools/rejeu/seance.py les rejoue dans un navigateur).
 *
 *   node tools/scenarios/jouer.mjs <url du déploiement> <scenario.json> <sortie.json>
 *   (jeton dans SELFTEST_TOKEN)
 *
 * scenario.json : { "id": "derivee", "ask": "C'est quoi une dérivée ?", "answers": "wrong", "turns": 4 }
 * answers : right | wrong (l'élève simulé se trompe, ce qui déclenche le diagnostic).
 */
import { readFileSync, writeFileSync } from "node:fs";

const [base, scenarioPath, outPath] = process.argv.slice(2);
const token = process.env.SELFTEST_TOKEN;
if (!base || !scenarioPath || !outPath || !token) {
  console.error("usage : SELFTEST_TOKEN=… node jouer.mjs <url> <scenario.json> <sortie.json>");
  process.exit(2);
}
const scenario = JSON.parse(readFileSync(scenarioPath, "utf8"));
const params = new URLSearchParams({
  ask: scenario.ask,
  answers: scenario.answers ?? "wrong",
  turns: String(scenario.turns ?? 4),
  raw: "1",
});
const started = Date.now();
const response = await fetch(`${base.replace(/\/$/, "")}/api/diagnostic?${params}`, { headers: { Authorization: `Bearer ${token}` } });
const report = await response.json();
const { raw, ...rest } = report;
writeFileSync(outPath, JSON.stringify({ scenario, ms: Date.now() - started, status: response.status, report: rest, turns: raw ?? [] }));
console.log(`${scenario.id} : HTTP ${response.status}, ${((Date.now() - started) / 1000).toFixed(0)} s, ${(raw ?? []).length} tours`);

#!/usr/bin/env node
/**
 * Banc d'évaluation : joue chaque question de questions.json contre /api/diagnostic
 * (séance complète, élève simulé) et enregistre les mesures dans resultats/<date>.json.
 *
 *   NESALIO_URL=https://app.nesalio.com SELFTEST_TOKEN=… node tools/eval/evaluer.mjs [--answers=wrong] [--turns=3] [--set=sn4]
 *
 * --set=sn4 joue questions-sn4.json (1re étape de SN 4 : factorisation, division de polynômes,
 * expressions rationnelles, partie entière). Une question peut exiger du contenu du programme :
 *   "mustUse": commandes de dessin attendues ("stepFunction"),
 *   "mustMention" / "mustNotMention": expressions régulières cherchées dans ce que Nesa dit, écrit
 *   et demande (méthode de la classe, bon résultat, notation québécoise).
 * Le rapport donne alors « programme : 3/4 » et ce qui manque.
 *
 * Chaque séance coûte des appels au modèle : à lancer avant/après un changement de consigne ou du moteur,
 * pour comparer les chiffres (gestes, phrases « dites sans montrer », rejets, latence).
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const base = process.env.NESALIO_URL ?? "https://app.nesalio.com";
const token = process.env.SELFTEST_TOKEN;
if (!token) {
  console.error("SELFTEST_TOKEN manquant (variable d'environnement).");
  process.exit(1);
}
const arg = (name, fallback) => process.argv.find((a) => a.startsWith(`--${name}=`))?.split("=")[1] ?? fallback;
const answers = arg("answers", "wrong");
const turns = arg("turns", "3");
const set = arg("set", "");
const questions = JSON.parse(readFileSync(join(here, set ? `questions-${set}.json` : "questions.json"), "utf8"));

/** Tout ce que l'élève voit et entend : paroles, dessins (avec leur texte), questions, résumé. */
function sessionText(report) {
  const steps = (report.steps ?? []).map((s) => [s.say, ...(s.do ?? []), s.check ?? ""].join(" "));
  return [...steps, ...(report.lesson?.summary ?? [])].join("\n").normalize("NFC");
}

/** Contenu du programme attendu : commandes, mentions exigées, mentions interdites. */
function programCheck(q, report) {
  const text = sessionText(report);
  const used = report.lesson?.commands ?? {};
  const misses = [];
  let total = 0;
  for (const type of q.mustUse ?? []) {
    total++;
    if (!used[type]) misses.push(`commande absente : ${type}`);
  }
  for (const pattern of q.mustMention ?? []) {
    total++;
    if (!new RegExp(pattern, "iu").test(text)) misses.push(`non mentionné : ${pattern}`);
  }
  for (const pattern of q.mustNotMention ?? []) {
    total++;
    if (new RegExp(pattern, "iu").test(text)) misses.push(`interdit : ${pattern}`);
  }
  return total === 0 ? null : { score: `${total - misses.length}/${total}`, ok: total - misses.length, total, misses };
}

const rows = [];
for (const q of questions) {
  const url = `${base}/api/diagnostic?ask=${encodeURIComponent(q.ask)}&answers=${answers}&turns=${turns}`;
  const started = Date.now();
  const report = await fetch(url, { headers: { Authorization: `Bearer ${token}` } }).then((r) => r.json());
  const lesson = report.lesson ?? {};
  const row = {
    id: q.id,
    gestures: lesson.gestures,
    unshown: lesson.unshown,
    rejected: lesson.rejected?.count,
    unknownTargets: lesson.unknownTargets?.length,
    cueCoverage: lesson.cueCoverage,
    goals: lesson.goals?.length ?? 0,
    firstStepMs: (report.turns ?? []).map((t) => t.firstStepMs),
    totalMs: Date.now() - started,
    error: lesson.error,
  };
  const program = programCheck(q, report);
  if (program) {
    row.program = program.score;
    if (program.misses.length > 0) row.programMisses = program.misses;
    row._ok = program.ok;
    row._total = program.total;
  }
  rows.push(row);
  console.log(JSON.stringify(row));
}
const total = (key) => rows.reduce((n, r) => n + (Number(r[key]) || 0), 0);
console.log(`\nGestes : ${total("gestures")} · dit sans montrer : ${total("unshown")} · rejets : ${total("rejected")} · cibles absentes : ${total("unknownTargets")}`);
if (total("_total") > 0) console.log(`Programme : ${total("_ok")}/${total("_total")} critères respectés`);
mkdirSync(join(here, "resultats"), { recursive: true });
writeFileSync(join(here, "resultats", `${set ? `${set}-` : ""}${new Date().toISOString().slice(0, 16).replace(":", "h")}.json`), JSON.stringify({ set: set || "general", answers, turns, rows }, null, 2));

/**
 * Relecture des séances enregistrées : rejoue chaque séance sur un tableau
 * (le même code que l'application) et mesure ce que le JSON permet de mesurer.
 *
 *   curl -H "Authorization: Bearer <jeton>" "<app>/api/seances?jour=AAAA-MM-JJ" -o seances.json
 *   npx tsx tools/analyse/seances.ts seances.json > rapport.md
 *
 * Par séance : questions, réponses de l'élève, attente, puis les mesures :
 * - chevauchements (domain/board/collisions, sur les empreintes du moteur) : un
 *   texte ou une étiquette posé sur un autre texte, sur un point, barré par un
 *   trait, dans une surface remplie ; chiffres de graduations qui se touchent ;
 * - objets sans repère : dessinés sans être rattachés à un mot de la phrase ({id}) ;
 * - relecture du tour (domain/tutor/turnReview) : « dit sans montrer », cibles
 *   absentes, phrases trop longues, gestes ;
 * - commandes refusées par le validateur, et commandes qui échouent au rejeu.
 * Puis la transcription : ce que Nesa a dit et dessiné, tour par tour.
 */
import { readFileSync } from "node:fs";
import type { TurnRecord } from "@/domain/sessionLog";
import { emptyBoard, type BoardState } from "@/domain/board/state";
import { collisions, covered, figureOutline, type CollisionKind } from "@/domain/board/collisions";
import { applyAction } from "@/domain/scene/commands";
import type { Step } from "@/domain/scene/schema";
import { reviewTurn } from "@/domain/tutor/turnReview";

type Input = { turns?: TurnRecord[] } | TurnRecord[];

/** Paires d'objets qui se gênent au tableau (voir domain/board/collisions). */
export function overlaps(state: BoardState): Array<{ a: string; b: string; kind: CollisionKind; ratio: number }> {
  return collisions(state);
}

/** Commandes dont le but est de faire bouger des objets : leurs mouvements sont voulus. */
const MOVING = new Set(["move", "rotate", "transform", "applyMatrix", "copy"]);

/** Objets déjà là (non effacés) dont la place ou l'étiquette a changé à cause d'une commande qui ne les visait pas. */
function imposedMoves(before: BoardState, after: BoardState, action: Step["do"] extends (infer A)[] | undefined ? A : never): number {
  if (MOVING.has(action.type)) return 0;
  let count = 0;
  for (const id of before.order) {
    const a = before.nodes[id];
    const b = after.nodes[id];
    if (!a || !b || a.erased || b.erased) continue;
    const moved = a.offset[0] !== b.offset[0] || a.offset[1] !== b.offset[1];
    const relabelled = "labelAt" in a && "labelAt" in b && JSON.stringify(a.labelAt) !== JSON.stringify(b.labelAt);
    if (moved || relabelled) count++;
  }
  return count;
}

interface SessionReport {
  session: string;
  ref: string | null;
  start: string;
  turns: TurnRecord[];
  overlaps: Map<string, { ratio: number; kind: CollisionKind; say: string }>;
  /** Superpositions demandées par la phrase (« je fais glisser l'image sur l'original ») : voulues, comptées à part. */
  wanted: Map<string, { ratio: number; kind: CollisionKind; say: string }>;
  /**
   * Images d'une transformation posées sur leur original (y compris l'image qui l'englobe, que le
   * détecteur de chevauchements tolère) ; hors l'image que la phrase fait glisser exprès et la figure
   * qui est sa propre image (axe de symétrie).
   */
  imagesOnFigure: Array<{ image: string; ratio: number; say: string }>;
  /** Transformations dessinées (image d'une figure). */
  images: number;
  uncued: number;
  /** Objets déjà au tableau que le moteur a déplacés sans que le modèle le demande (pile de calculs, textes poussés…). */
  shifted: number;
  drawn: number;
  replayErrors: string[];
  unshown: Array<{ say: string; word: string }>;
  missingTargets: Set<string>;
  longSentences: number;
  gestures: number;
  steps: number;
  rejected: string[];
  checks: { right: number; total: number };
  firstStepMs: number[];
  cancelled: number;
  errors: string[];
}

function steps(turn: TurnRecord): Step[] {
  return turn.events.filter((e): e is Extract<typeof e, { kind: "step" }> => e.kind === "step");
}

export function analyse(turns: readonly TurnRecord[]): SessionReport[] {
  const sessions = new Map<string, SessionReport>();
  const boards = new Map<string, BoardState>();
  for (const turn of turns) {
    // L'identifiant entier : deux séances dont l'identifiant commence pareil restent distinctes.
    const key = turn.session ?? "sans-session";
    let s = sessions.get(key);
    if (!s) {
      s = {
        session: key, ref: turn.ref ?? null, start: turn.at, turns: [], overlaps: new Map(), wanted: new Map(), imagesOnFigure: [], images: 0, uncued: 0, shifted: 0, drawn: 0, replayErrors: [],
        unshown: [], missingTargets: new Set(), longSentences: 0, gestures: 0, steps: 0, rejected: [], checks: { right: 0, total: 0 },
        firstStepMs: [], cancelled: 0, errors: [],
      };
      sessions.set(key, s);
    }
    if (!s.ref && turn.ref) s.ref = turn.ref;
    s.turns.push(turn);
    // Une nouvelle question ouvre une nouvelle explication : le tableau repart de zéro.
    let board = turn.mode === "question" || !boards.has(key) ? emptyBoard() : boards.get(key)!;
    const turnSteps = steps(turn);
    for (const step of turnSteps) {
      const before = new Set(Object.keys(board.nodes));
      /** Ce que la phrase fait bouger exprès (glisser sur l'original, copie sur place, rotation) : sa superposition est voulue. */
      const moved = new Set<string>();
      for (const action of step.do ?? []) {
        if (!MOVING.has(action.type)) continue;
        const a = action as { id?: string; target?: string; targets?: string[] };
        for (const id of [a.id, a.target, ...(a.targets ?? [])]) if (id) moved.add(id);
      }
      for (const action of step.do ?? []) {
        try {
          const previous = board;
          board = applyAction(board, action, { start: 0, duration: 0 });
          s.shifted += imposedMoves(previous, board, action);
          if (action.type === "image" && board.groups[action.id] && !previous.groups[action.id]) {
            s.images++;
            const original = figureOutline(board, action.target);
            const image = figureOutline(board, action.id);
            if (original && image && !moved.has(action.id)) {
              const a = covered(original, image);
              const b = covered(image, original);
              const itself = Math.min(a, b) > 0.95;
              if (!itself && Math.max(a, b) > 0.05) s.imagesOnFigure.push({ image: action.id, ratio: Math.round(Math.max(a, b) * 100) / 100, say: step.say.slice(0, 90) });
            }
          }
        } catch (error) {
          s.replayErrors.push(`${action.type} : ${(error as Error).message}`.slice(0, 160));
        }
      }
      const created = Object.keys(board.nodes).filter((id) => !before.has(id) && board.nodes[id]?.type !== "text");
      s.drawn += created.length;
      s.uncued += created.filter((id) => !(step.cues && id in step.cues)).length;
      const groupsOf = (id: string) => Object.values(board.groups).filter((g) => g.members.includes(id)).map((g) => g.id);
      // « A·étiquette » : l'étiquette du point A, qui bouge avec lui.
      const intended = (raw: string) => {
        const id = raw.split("·")[0]!;
        return [id, ...groupsOf(id)].some((x) => moved.has(x) || [...moved].some((m) => x.startsWith(`${m}-`)));
      };
      for (const o of overlaps(board)) {
        const pair = o.kind === "graduations" ? `graduations ${o.a}` : `${o.a} × ${o.b}`;
        const into = o.kind !== "graduations" && (intended(o.a) || intended(o.b)) ? s.wanted : s.overlaps;
        // Une superposition voulue le reste tant qu'elle dure (les phrases suivantes ne la recomptent pas).
        if (s.wanted.has(pair) || s.overlaps.has(pair)) continue;
        into.set(pair, { ratio: o.ratio, kind: o.kind, say: step.say.slice(0, 90) });
      }
    }
    boards.set(key, board);
    const review = reviewTurn(turnSteps, board);
    s.steps += review.steps;
    s.gestures += review.gestures;
    s.longSentences += review.longSentences;
    s.unshown.push(...review.unshown);
    review.missingTargets.forEach((t) => s!.missingTargets.add(t));
    for (const e of turn.events) {
      if (e.kind === "await" && e.rejected) s.rejected.push(...e.rejected);
      if (e.kind === "error") s.errors.push(`${e.code} : ${e.message}`);
    }
    if (turn.answer && turn.answer.correct !== null) {
      s.checks.total++;
      if (turn.answer.correct) s.checks.right++;
    }
    if (turn.latencyMs.firstStep !== undefined) s.firstStepMs.push(turn.latencyMs.firstStep);
    if (turn.outcome !== "complete") s.cancelled++;
  }
  return [...sessions.values()];
}

const sec = (ms: number) => `${(ms / 1000).toFixed(1)} s`;
const median = (xs: number[]) => (xs.length ? [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]! : 0);

export function report(sessions: readonly SessionReport[], withTranscript = true): string {
  const lines: string[] = [];
  const allFirst = sessions.flatMap((s) => s.firstStepMs);
  const sum = (f: (s: SessionReport) => number) => sessions.reduce((t, s) => t + f(s), 0);
  lines.push(`# Séances : ${sessions.length} séances, ${sum((s) => s.turns.length)} tours, ${sum((s) => s.steps)} phrases`);
  lines.push("");
  lines.push(`- Attente avant la première phrase : médiane ${sec(median(allFirst))}, max ${sec(Math.max(0, ...allFirst))}`);
  const byKind = (kind: CollisionKind) => sum((s) => [...s.overlaps.values()].filter((o) => o.kind === kind).length);
  lines.push(
    `- Chevauchements (paires distinctes) : ${sum((s) => s.overlaps.size)} · texte sur texte ${byKind("texte")} · sur un point ${byKind("point")} · barré par un trait ${byKind("trait")} · dans une surface ${byKind("surface")} · graduations ${byKind("graduations")} · dessins l'un sur l'autre ${byKind("dessins")}`,
  );
  lines.push(`- Superpositions voulues (l'objet que la phrase fait glisser, copie ou tourne) : ${sum((s) => s.wanted.size)}`);
  lines.push(`- Images posées sur leur original (englobée comprise) : ${sum((s) => s.imagesOnFigure.length)} sur ${sum((s) => s.images)} transformations`);
  lines.push(`- Déplacements imposés par le moteur (objets déjà au tableau) : ${sum((s) => s.shifted)}`);
  lines.push(`- Objets dessinés sans repère dans la phrase : ${sum((s) => s.uncued)} sur ${sum((s) => s.drawn)}`);
  lines.push(`- « Dit sans montrer » : ${sum((s) => s.unshown.length)} · cibles absentes : ${sum((s) => s.missingTargets.size)} · phrases trop longues : ${sum((s) => s.longSentences)}`);
  lines.push(`- Commandes refusées : ${sum((s) => s.rejected.length)} · erreurs au rejeu : ${sum((s) => s.replayErrors.length)} · erreurs envoyées : ${sum((s) => s.errors.length)}`);
  lines.push(`- Vérifications réussies : ${sum((s) => s.checks.right)} / ${sum((s) => s.checks.total)} · tours interrompus : ${sum((s) => s.cancelled)}`);
  for (const s of sessions) {
    lines.push("", `## Séance ${s.session.replace(/-/g, "").slice(0, 8)}${s.ref ? ` (inscription ${s.ref})` : ""} · ${s.start.slice(11, 16)} UTC · ${s.turns.length} tours`);
    lines.push(
      `Attente médiane ${sec(median(s.firstStepMs))} · ${s.steps} phrases, ${s.gestures} gestes · sans repère ${s.uncued}/${s.drawn} · vérifications ${s.checks.right}/${s.checks.total} · interrompus ${s.cancelled}`,
    );
    for (const [pair, o] of s.overlaps) {
      const amount = o.kind === "trait" ? `${o.ratio} points du trait` : o.kind === "graduations" ? `${o.ratio} chiffres` : `${Math.round(o.ratio * 100)} %`;
      lines.push(`- Chevauchement (${o.kind}) ${pair} (${amount}) pendant « ${o.say} »`);
    }
    for (const o of s.imagesOnFigure) lines.push(`- Image sur l'original ${o.image} (${Math.round(o.ratio * 100)} %) pendant « ${o.say} »`);
    for (const u of s.unshown) lines.push(`- Dit sans montrer (« ${u.word} ») : « ${u.say} »`);
    if (s.missingTargets.size) lines.push(`- Cibles absentes : ${[...s.missingTargets].join(", ")}`);
    for (const r of s.rejected) lines.push(`- Refusé : ${r}`);
    for (const e of s.replayErrors) lines.push(`- Échec au rejeu : ${e}`);
    for (const e of s.errors) lines.push(`- Erreur envoyée à l'élève : ${e}`);
    if (!withTranscript) continue;
    lines.push("");
    for (const t of s.turns) {
      const head = t.mode === "continue" && t.answer
        ? `**Élève répond** « ${t.answer.picked} » à « ${t.answer.prompt} » (${t.answer.correct === null ? "sans bonne réponse" : t.answer.correct ? "juste" : "faux"}${t.answer.misconception ? `, erreur : ${t.answer.misconception}` : ""})`
        : `**Élève (${t.mode})** : ${t.question}`;
      lines.push(`${head} · ${t.outcome}, 1re phrase ${t.latencyMs.firstStep !== undefined ? sec(t.latencyMs.firstStep) : "—"}, tour ${sec(t.latencyMs.total)}`);
      for (const e of t.events) {
        if (e.kind === "lesson") lines.push(`  - Leçon « ${e.title} »${e.goals?.length ? ` · objectifs : ${e.goals.join(" / ")}` : ""}`);
        if (e.kind === "step") {
          const types = (e.do ?? []).map((a) => a.type).join(", ");
          lines.push(`  - ${e.say}${types ? `  [${types}]` : ""}`);
          if (e.check) lines.push(`    ? ${e.check.prompt} → ${e.check.choices.map((c, i) => (i === e.check!.answer ? `*${c}*` : c)).join(" | ")}`);
        }
        if (e.kind === "diagnosis") {
          const gaps = e.gaps.map((g) => `${g.notion}${g.level ? ` (${g.level})` : ""} : ${g.status}${g.evidence ? ` [${g.evidence}]` : ""}`);
          lines.push(`    🩺 ${gaps.length ? gaps.join(" ; ") : "aucune lacune"}${e.strengths.length ? ` · forces : ${e.strengths.join(" ; ")}` : ""}${e.next ? ` · suite : ${e.next}` : ""}`);
        }
        if (e.kind === "end") {
          lines.push(`  - Fin : ${e.summary.join(" / ")}`);
          if (e.noticed) lines.push(`  - Remarqué : forces ${e.noticed.strengths.join(" ; ")} · à travailler ${e.noticed.toWork.join(" ; ")}`);
        }
      }
    }
  }
  return lines.join("\n");
}

if (process.argv[2]) {
  const raw = JSON.parse(readFileSync(process.argv[2], "utf8")) as Input;
  const turns = Array.isArray(raw) ? raw : (raw.turns ?? []);
  process.stdout.write(report(analyse(turns), !process.argv.includes("--sans-transcription")) + "\n");
}

/**
 * POST /api/tutor — reçoit la question de l'élève et renvoie l'explication
 * en flux NDJSON (un événement par ligne), au fur et à mesure que le modèle
 * la génère. Les identifiants du modèle ne quittent jamais le serveur.
 * Le tour est enregistré pour améliorer l'outil (domain/sessionLog.ts).
 */
import type { StreamEvent } from "@/domain/scene/schema";
import { encodeLine } from "@/domain/tutor/ndjson";
import { TutorRequestSchema } from "@/domain/tutor/request";
import { readAiConfig } from "@/server/config";
import { createSessionLimits } from "@/server/rateLimit";
import { refFromHeaders, shortSession } from "@/domain/session";
import { streamChatCompletion } from "@/server/tutor/chatCompletions";
import { tutorEvents } from "@/server/tutor/service";
import { after } from "next/server";
import { createTurnRecorder } from "@/domain/sessionLog";
import { recordEnv, saveTurn } from "@/server/sessionStore";
import { withRecording } from "@/server/tutor/recording";
import { readBoundedText } from "@/server/http";
import { requireAccount } from "@/server/account";

export const runtime = "nodejs";
// Un tour où le modèle réfléchit longtemps dépasse parfois 60 s : coupé, il finissait sans question.
export const maxDuration = 180;

// Le contexte inclut désormais les observations bornées par notion (16 × 8 au plus).
const MAX_BODY_BYTES = 96_000;
// Par session de navigation : une séance compte plusieurs tours (un appel par réponse de l'élève),
// soit environ 8 séances par 10 minutes ; une même adresse (une classe) peut en ouvrir 12 fois plus.
const limiter = createSessionLimits({ limit: 40, windowMs: 10 * 60_000 });

const NDJSON_HEADERS = {
  "Content-Type": "application/x-ndjson; charset=utf-8",
  "Cache-Control": "no-store",
  "X-Accel-Buffering": "no",
};

function single(event: StreamEvent, status: number, extra: Record<string, string> = {}) {
  return new Response(encodeLine(event), { status, headers: { ...NDJSON_HEADERS, ...extra } });
}

export async function POST(request: Request): Promise<Response> {
  const access = await requireAccount(request, true);
  if (!access.ok) return access.response;
  // Limiter aussi les requêtes invalides avant leur lecture et leur validation.
  const limit = limiter.check(request.headers, undefined, access.userId);
  const tag = limit.session ? `[session ${shortSession(limit.session)}]` : "[sans session]";
  if (!limit.allowed) {
    return single(
      { kind: "error", code: "rate_limited", message: "Tu as posé beaucoup de questions d'un coup. Réessaie dans quelques minutes." },
      429,
      { "Retry-After": String(limit.retryAfterSeconds) },
    );
  }

  const raw = await readBoundedText(request, MAX_BODY_BYTES);
  if (!raw.ok) return single({ kind: "error", code: "bad_request", message: raw.status === 413 ? "Question trop longue." : "Requête illisible." }, raw.status);
  let body: unknown;
  try { body = JSON.parse(raw.text); }
  catch { return single({ kind: "error", code: "bad_request", message: "Requête illisible." }, 400); }
  const parsed = TutorRequestSchema.safeParse(body);
  if (!parsed.success) return single({ kind: "error", code: "bad_request", message: "Requête invalide." }, 400);

  const config = readAiConfig(request.headers);
  // Chaque tour est enregistré (sans nom, IP ni audio) pour améliorer Nesalio ; écrit après la réponse.
  const recorder = createTurnRecorder({
    request: parsed.data,
    session: limit.session,
    ref: refFromHeaders(request.headers),
    env: recordEnv(),
    source: config.chat ? "model" : "demo",
    model: config.chat?.model,
    startedAt: new Date(),
    clock: { now: () => Date.now() },
  });
  after(() => saveTurn(recorder.record()));
  const events = withRecording(
    tutorEvents(parsed.data, {
      provider: config.chat,
      completion: streamChatCompletion,
      signal: request.signal,
      log: (message, detail) => console.warn(tag, message, detail),
    }),
    recorder,
  );

  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        const { value, done } = await events.next();
        if (done) controller.close();
        else controller.enqueue(encoder.encode(encodeLine(value)));
      } catch (error) {
        console.error(tag, "tutor: flux interrompu", error);
        controller.close();
      }
    },
    async cancel() {
      await events.return(undefined);
    },
  });

  return new Response(stream, { status: 200, headers: NDJSON_HEADERS });
}

/**
 * POST /api/voice — la voix de Nesa : { text } → audio (WAV ou MP3), avec la
 * partie vraiment parlée dans l'en-tête X-Speech-Span (« début,fin » en ms).
 * Réponse 503 si aucune voix n'est configurée : le navigateur se rabat alors
 * sur sa propre synthèse vocale.
 */
import { z } from "zod";
import { speechSpanOf, synthesizeSpeech } from "@/server/ai/audio";
import { readAiConfig } from "@/server/config";
import { checkRate, jsonError, readJson } from "@/server/http";
import { createSessionLimits } from "@/server/rateLimit";
import { isUnavailable } from "@/server/tutor/service";
import { SPEECH_SPAN_HEADER } from "@/domain/audio/speechSpan";
import { requireAccount } from "@/server/account";

export const runtime = "nodejs";
export const maxDuration = 30;

const Body = z.object({ text: z.string().trim().min(1).max(400) });
// Une séance compte une dizaine de phrases : la limite est large mais réelle.
const limiter = createSessionLimits({ limit: 160, windowMs: 10 * 60_000 });

export async function POST(request: Request): Promise<Response> {
  const access = await requireAccount(request);
  if (!access.ok) return access.response;
  const limited = checkRate(limiter, request, access.userId);
  if (limited) return limited;
  const read = await readJson(request, 4_000);
  if (!read.ok) return read.response;
  const parsed = Body.safeParse(read.body);
  if (!parsed.success) return jsonError(400, "Texte invalide.");

  const config = readAiConfig(request.headers);
  if (!config.gatewayToken) return jsonError(503, "Voix non configurée.");

  try {
    const { audio, mediaType } = await synthesizeSpeech({
      token: config.gatewayToken,
      model: config.voice.model,
      voice: config.voice.voice,
      instructions: config.voice.instructions,
      text: parsed.data.text,
      signal: request.signal,
    });
    // Partie vraiment parlée (sans les silences du début et de la fin) : le lecteur y cale les repères {id}.
    const span = speechSpanOf(audio, mediaType);
    return new Response(audio as unknown as BodyInit, {
      headers: {
        "Content-Type": mediaType,
        "Cache-Control": "private, max-age=3600",
        ...(span ? { [SPEECH_SPAN_HEADER]: `${span.startMs},${span.endMs}` } : {}),
      },
    });
  } catch (error) {
    console.warn("voice: échec de la synthèse", error);
    // 503 : le navigateur passe tout de suite à sa propre voix.
    if (isUnavailable(error)) return jsonError(503, "Voix indisponible pour le moment.");
    return jsonError(502, "La voix n'a pas pu être générée.");
  }
}

/**
 * POST /api/transcribe — ce que l'élève a dit au micro :
 * { audio: base64, mediaType } → { text }.
 */
import { z } from "zod";
import { transcribeAudio } from "@/server/ai/audio";
import { readAiConfig } from "@/server/config";
import { checkRate, jsonError, readJson } from "@/server/http";
import { createSessionLimits } from "@/server/rateLimit";
import { isUnavailable } from "@/server/tutor/service";
import { requireAccount } from "@/server/account";

export const runtime = "nodejs";
export const maxDuration = 30;

/** Environ 45 secondes d'audio compressé, encodé en base64. */
const MAX_BODY_BYTES = 3_000_000;
const MEDIA_TYPES = ["audio/webm", "audio/ogg", "audio/mp4", "audio/mpeg", "audio/wav", "audio/x-m4a"];

const Body = z.object({
  audio: z.string().min(100),
  mediaType: z.string().refine((type) => MEDIA_TYPES.some((allowed) => type.startsWith(allowed)), "Format audio non pris en charge"),
});
const limiter = createSessionLimits({ limit: 40, windowMs: 10 * 60_000 });

export async function POST(request: Request): Promise<Response> {
  const access = await requireAccount(request);
  if (!access.ok) return access.response;
  const limited = checkRate(limiter, request, access.userId);
  if (limited) return limited;
  const read = await readJson(request, MAX_BODY_BYTES);
  if (!read.ok) return read.response;
  const parsed = Body.safeParse(read.body);
  if (!parsed.success) return jsonError(400, "Audio invalide.");

  const config = readAiConfig(request.headers);
  if (!config.gatewayToken) return jsonError(503, "Transcription non configurée.");

  try {
    const text = await transcribeAudio({
      token: config.gatewayToken,
      model: config.transcription.model,
      audioBase64: parsed.data.audio,
      // Le paramètre « codecs » (audio/webm;codecs=opus) n'est pas utile au modèle.
      mediaType: parsed.data.mediaType.split(";")[0]!,
      signal: request.signal,
    });
    return Response.json({ text }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    console.warn("transcribe: échec", error);
    // 503 : le navigateur passe à sa propre reconnaissance vocale.
    if (isUnavailable(error)) return jsonError(503, "Transcription indisponible pour le moment.");
    return jsonError(502, "Je n'ai pas réussi à comprendre l'enregistrement.");
  }
}

/**
